193	int32_t errno_to_user_errno_inner(int32_t kern_err_no)
194	{
195	    uint32_t drv_kern_err_no = (uint32_t)kern_err_no;
196	
197	    if (kern_err_no < 0) {
198	        if (kern_err_no == -1) {
199	            return DRV_ERROR_IOCRL_FAIL;
200	        }
201	        drv_kern_err_no = (uint32_t)(-kern_err_no);
202	    }
203	    if (drv_kern_err_no >= ERROR_NUN_MAX) {
204	        if (drv_kern_err_no == DRV_KERNEL_ERROR_RESUME) {
205	            return DRV_ERROR_RESUME;
206	        } else if (drv_kern_err_no == DRV_KERNEL_ERROR_DUP_CONFIG) {
207	            return DEV_ERROR_DUP_CONFIG;
208	        } else if (drv_kern_err_no == DRV_KERNEL_ERROR_POWER_OP_FAIL) {
209	            return DRV_ERROR_POWER_OP_FAIL;
210	        } else {
211	            return DRV_ERROR_IOCRL_FAIL;
212	        }
213	    } else if (drv_kern_err_no == 0) {
214	        return DRV_ERROR_NONE;
215	    } else if (user_err[drv_kern_err_no] == 0) {
216	        return DRV_ERROR_IOCRL_FAIL;
217	    } else {
218	        ;
219	    }
220	    return user_err[drv_kern_err_no];
221	}
