282	const char *drv_get_tm_default(void)
283	{
284	    static char tmbuf[BUFF_LENTH] = {0};
285	    struct timespec ts;
286	    struct tm *tm_now = NULL;
287	    int32_t ret;
288	    static pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
289	
290	    (void)pthread_mutex_lock(&lock);
291	    if (clock_gettime(CLOCK_REALTIME, &ts) != 0) {
292	        (void)pthread_mutex_unlock(&lock);
293	        return NULL;
294	    }
295	
296	    tm_now = localtime(&ts.tv_sec);
297	    if (tm_now == NULL) {
298	        (void)pthread_mutex_unlock(&lock);
299	        return NULL;
300	    }
301	
302	    ret = sprintf_s(tmbuf, BUFF_LENTH, "[%d-%02d-%02d-%02d:%02d:%02d:%06d]", tm_now->tm_year + DRV_LOG_START_TIME,
303	                    tm_now->tm_mon + 1, tm_now->tm_mday, tm_now->tm_hour, tm_now->tm_min, tm_now->tm_sec,
304	                    (int32_t)(ts.tv_nsec / DRV_NSEC_PER_USECOND));
305	    if (ret < 0) {
306	        (void)pthread_mutex_unlock(&lock);
307	        return NULL;
308	    }
309	
310	    (void)pthread_mutex_unlock(&lock);
311	    return tmbuf;
312	}
