363	int32_t drv_log_out_handle_register_inner(struct log_out_handle *handle, size_t input_size, uint32_t flag)
364	{
365	    if (input_size != sizeof(struct log_out_handle)) {
366	        (void)printf("Log_out_handle_register failed. (input_size=%zu; size_log_out_handle=%zu)\n", input_size,
367	                     sizeof(struct log_out_handle)); // lint !e559
368	        return DRV_ERROR_INVALID_VALUE;
369	    }
370	
371	    if (handle == NULL) {
372	        (void)printf("Log_out_handle_register failed, handle is NULL.\n");
373	        return DRV_ERROR_INVALID_VALUE;
374	    }
375	
376	    if (handle->DlogInner == NULL) {
377	        (void)printf("Log_out_handle_register failed, the member DlogInner in handle is NULL.\n");
378	        return DRV_ERROR_INVALID_VALUE;
379	    }
380	
381	    if (handle->logLevel >= (uint32_t)LOG_TOOL_LEVEL_TYPE_MAX) {
382	        (void)printf("Log_out_handle_register failed. (handle->logLevel=%u)\n", handle->logLevel);
383	        return DRV_ERROR_INVALID_VALUE;
384	    }
385	
386	    g_run_log_status = flag;
387	    drv_log_tool_console_level = drv_log_level_tool_to_glibc(handle->logLevel);
388	    g_log_print_info.con_log_level = &drv_log_tool_console_level;
389	    g_log_print_info.log_get_level_string = drv_log_get_level_str;
390	    g_log_print_info.log_get_print_time = drv_get_tm;
391	    g_log_print_info.log_level_shift = drv_log_level_glibc_to_tool;
392	    g_log_print_info.log_print = handle->DlogInner;
393	
394	    return DRV_ERROR_NONE;
395	}
