218	static int32_t MsnOptionGetValueInRange(const char *arg, const char *option, int64_t *value, int32_t min, int32_t max)
219	{
220	    int64_t num = -1;
221	    if (LogStrToInt(arg, &num) != LOG_SUCCESS) {
222	        MSNPU_PRINT_ERROR("Invalid value '%s' for --%s , please input a number in range[%d-%d].",
223	            arg, option, min, max);
224	        return EN_ERROR;
225	    }
226	    char tmp[NUMBER_STR_LEN] = {0};
227	    int32_t ret = sprintf_s(tmp, NUMBER_STR_LEN, "%ld", num);
228	    if (ret < 0) {
229	        SELF_LOG_ERROR("call sprintf failed.");
230	        return EN_ERROR;
231	    }
232	    if (strcmp(arg, tmp) != 0) {
233	        MSNPU_PRINT_ERROR("Invalid value '%s' for --%s", arg, option);
234	        return EN_ERROR;
235	    }
236	    if ((num < min) || num > max) {
237	        MSNPU_PRINT_ERROR("Invalid value '%s' for --%s, please input in range [%d-%d].", arg, option, min, max);
238	        return EN_ERROR;
239	    }
240	
241	    *value = num;
242	    return EN_OK;
243	}
