324	STATIC int32_t MsnHandleCoreId(DfxCoreSetMask *coreMask, const char *arg)
325	{
326	    uint8_t value = 0;
327	    char *context = NULL;
328	    char inputArg[MAX_VALUE_STR_LEN] = {0};
329	    errno_t err = strcpy_s(inputArg, MAX_VALUE_STR_LEN, arg);
330	    ONE_ACT_ERR_LOG(err != EOK, return EN_ERROR, "Call strcpy_s fail for coreid arg:%s.", arg);
331	
332	    uint8_t count = 0;
333	    char *token = strtok_s(inputArg, ",", &context);
334	    while (token != NULL) {
335	        int64_t num = 0;
336	        if (MsnOptionGetValueInRange(token, "coreid", &num, 0, UINT8_MAX) != EN_OK) {
337	            return EN_ERROR;
338	        }
339	
340	        value = (uint8_t)num;
341	        if (count >= CORE_ID_MAX) {
342	            MSNPU_PRINT_ERROR("Input core id count more than %d.", CORE_ID_MAX);
343	            return EN_ERROR;
344	        }
345	        for (uint8_t i = 0; i < count; i++) {
346	            if (coreMask->coreId[i] == value) {
347	                MSNPU_PRINT_ERROR("Duplicate input core id '%hhu'.", value);
348	                return EN_ERROR;
349	            }
350	        }
351	        coreMask->coreId[count++] = value;
352	
353	        token = strtok_s(NULL, ",", &context);
354	    }
355	
356	    uint8_t commaNum = 0;
357	    const char *p = arg;
358	    while (*p) {
359	        if (*p == ',') {
360	            commaNum++;
361	        }
362	        p++;
363	    }
364	    if (commaNum >= count) {
365	        MSNPU_PRINT_ERROR("Input --coreid %s is invalid.", arg);
366	        return EN_ERROR;
367	    }
368	    coreMask->configNum = count;
369	
370	    return EN_OK;
371	}
