373	STATIC int32_t MsnSetCoreId(ArgInfo *argInfo, const char *arg)
374	{
375	    if (argInfo->coreSwitch < 0) {
376	        MSNPU_PRINT_ERROR("Input '--aic_switch' or '--aiv_switch' first to use '--coreid'.");
377	        return EN_ERROR;
378	    }
379	    DfxCoreSetMask *setCoreMask = (DfxCoreSetMask *)argInfo->value;
380	    setCoreMask->coreSwitch = (uint8_t)argInfo->coreSwitch;
381	
382	    if (strcmp(arg, RESET_COREID_FLAG) == 0) {
383	        // --coreid=0xFFFF means reset all core
384	        if (argInfo->coreSwitch != ENABLE_CORE) {
385	            MSNPU_PRINT_ERROR("The core id '0xFFFF' can only be used with '--aic_switch 1' or '--aiv_switch 1'");
386	            return EN_ERROR;
387	        }
388	        setCoreMask->coreSwitch = RESTORE_CORE;
389	    } else {
390	        if (MsnHandleCoreId(setCoreMask, arg) != EN_OK) {
391	            return EN_ERROR;
392	        }
393	    }
394	
395	    argInfo->valueLen = (uint16_t)sizeof(DfxCoreSetMask);
396	    return EN_OK;
397	}
