420	STATIC int32_t MsnCheckLevelStr(char *level, int32_t length, LogLevelType levelType)
421	{
422	    (void)length;
423	    if (levelType == LOGLEVEL_EVENT) {
424	        if ((strcmp(level, ENABLE_STR) == 0) || (strcmp(level, DISABLE_STR) == 0)) {
425	            return EN_OK;
426	        } else {
427	            MSNPU_PRINT_ERROR("Event level '%s' is invalid", level);
428	            return EN_ERROR;
429	        }
430	    }
431	    if (levelType == LOGLEVEL_MODULE) {
432	        char *pend = strchr(level, ':');
433	        if (pend == NULL) {
434	            MSNPU_PRINT_ERROR("Module level info format error, please input 'module:level' format.");
435	            return EN_ERROR;
436	        }
437	        *pend = '\0';
438	        const ModuleInfo *moduleInfo = GetModuleInfoByName(level);
439	        if (moduleInfo == NULL) {
440	            MSNPU_PRINT_ERROR("Module name '%s' does not exist.", level);
441	            return EN_ERROR;
442	        }
443	        *pend = ':';
444	        level = pend + 1;
445	    }
446	
447	    int32_t levelId = GetLevelIdByName(level);
448	    if ((levelId < LOG_MIN_LEVEL) || (levelId > LOG_MAX_LEVEL)) {
449	        MSNPU_PRINT_ERROR("Level '%s' is invalid, You can execute 'config --help' for example value.", level);
450	        return EN_ERROR;
451	    }
452	    return EN_OK;
453	}
