455	STATIC int32_t MsnSetLogLevel(ArgInfo *argInfo, const char *arg, LogLevelType levelType)
456	{
457	    if (argInfo->subCmd != LOG_LEVEL) {
458	        MSNPU_PRINT_ERROR("Must input '--log' before --global, --module or --event.");
459	        return EN_ERROR;
460	    }
461	
462	    if (argInfo->valueLen != 0) {
463	        MSNPU_PRINT_ERROR("Only one command is supported at a time.");
464	        return EN_ERROR;
465	    }
466	
467	    char level[MAX_VALUE_STR_LEN] = {0};
468	    errno_t err = strcpy_s(level, MAX_VALUE_STR_LEN, arg);
469	    if (err != EOK) {
470	        if (err == ERANGE_AND_RESET) {
471	            MSNPU_PRINT_ERROR("Input level '%s' is invalid.", arg);
472	        }
473	        SELF_LOG_ERROR("strcpy_s failed for log level");
474	        return EN_ERROR;
475	    }
476	    MsnToUpper(level, LogStrlen(level));
477	    if (MsnCheckLevelStr(level, MAX_VALUE_STR_LEN, levelType) != EN_OK) {
478	        return EN_ERROR;
479	    }
480	    int32_t ret = sprintf_s(argInfo->value, MAX_VALUE_STR_LEN, "SetLogLevel(%d)[%s]", levelType, level);
481	    if (ret == -1) {
482	        SELF_LOG_ERROR("sprintf failed for log level");
483	        return EN_ERROR;
484	    }
485	    argInfo->valueLen = (uint16_t)strlen(argInfo->value) + 1U;
486	    return EN_OK;
487	}
