489	STATIC int32_t HandleCommonCmd(int32_t opt, ArgInfo *argInfo)
490	{
491	    switch (opt) {
492	        case CONFIG_ARGS_DOCKER:
493	            if (MsnIsDockerEnv()) {
494	                argInfo->dockerFlag = 1;
495	                return EN_OK;
496	            } else {
497	                MSNPU_PRINT_ERROR("--docker only used in docker env.");
498	                return EN_ERROR;
499	            }
500	        case CONFIG_ARGS_GET:
501	            if (argInfo->cmdType != INVALID_CMD) {
502	                MSNPU_PRINT_ERROR("Only one option(--set or --get) is supported at a time.");
503	                return EN_ERROR;
504	            }
505	            argInfo->cmdType = CONFIG_GET;
506	            return EN_OK;
507	        case CONFIG_ARGS_SET:
508	            if (argInfo->cmdType != INVALID_CMD) {
509	                MSNPU_PRINT_ERROR("Only one option(--set or --get) is supported at a time.");
510	                return EN_ERROR;
511	            }
512	            argInfo->cmdType = CONFIG_SET;
513	            return EN_OK;
514	        case CONFIG_ARGS_HELP:
515	            MsnPrintConfigHelp();
516	            return EN_INVALID_PARAM;
517	        case CONFIG_ARGS_DEVICE:
518	            if (MsnSetDeviceId(argInfo, mmGetOptArg()) != EN_OK) {
519	                return EN_ERROR;
520	            }
521	            return EN_OK;
522	        default:
523	            return EN_ERROR;
524	    }
525	}
