576	STATIC int32_t MsnConfigCmdCheck(ArgInfo *argInfo)
577	{
578	    if (argInfo->subCmd == LOG_LEVEL) {
579	        if (strncmp(argInfo->value, STE_LOG_LEVEL_HEAD, strlen(STE_LOG_LEVEL_HEAD)) != 0) {
580	            MSNPU_PRINT_ERROR("Option '--log' must used with one of '--global', '--event' and '--module'");
581	            return EN_ERROR;
582	        }
583	    }
584	    if ((argInfo->coreSwitch >= 0) && (argInfo->valueLen == 0)) {
585	        MSNPU_PRINT_ERROR("Option '--aic_switch' or '--aiv_switch' must use with '--coreid'");
586	        return EN_ERROR;
587	    }
588	    if ((argInfo->cmdType == INVALID_CMD) || ((argInfo->cmdType == CONFIG_SET) && (argInfo->valueLen == 0))) {
589	        MSNPU_PRINT_ERROR("Invalid command.");
590	        MsnPrintConfigHelp();
591	        return EN_ERROR;
592	    }
593	    if (MsnIsDockerEnv() && !(argInfo->dockerFlag != 0)) {
594	        MSNPU_PRINT_ERROR("msnpureport in docker should be used with --docker.");
595	        return EN_ERROR;
596	    }
597	
598	    return EN_OK;
599	}
