601	STATIC int32_t MsnGetConfigOptions(int32_t argc, char **argv, ArgInfo *argInfo)
602	{
603	    argInfo->subCmd = (uint32_t)INVALID_TYPE;
604	    int32_t opt = 0;
605	    int32_t optionIndex = 0;
606	    while ((opt = mmGetOptLong(argc, argv, CONFIG_OPT, CONFIG_OPTS, &optionIndex)) != -1) {
607	        switch (opt) {
608	            case CONFIG_ARGS_DOCKER:
609	            case CONFIG_ARGS_GET:
610	            case CONFIG_ARGS_SET:
611	            case CONFIG_ARGS_HELP:
612	            case CONFIG_ARGS_DEVICE:
613	                if (HandleCommonCmd(opt, argInfo) != EN_OK) {
614	                    return EN_ERROR;
615	                }
616	                break;
617	            case CONFIG_ARGS_ICACHE_CHECK:
618	            case CONFIG_ARGS_ACCELERATOR_RECOVER:
619	            case CONFIG_ARGS_AIC_SWITCH:
620	            case CONFIG_ARGS_AIV_SWITCH:
621	            case CONFIG_ARGS_SINGLE_COMMIT:
622	            case CONFIG_ARGS_CORE_ID:
623	                if (HandleAicErrorCmd(opt, mmGetOptArg(), argInfo) != EN_OK) {
624	                    return EN_ERROR;
625	                }
626	                break;
627	            case CONFIG_ARGS_LOG_LEVEL:
628	            case CONFIG_ARGS_GLOBAL_LEVEL:
629	            case CONFIG_ARGS_MODULE_LEVEL:
630	            case CONFIG_ARGS_EVENT_LEVEL:
631	                if (HandleLogLevelCmd(opt, argInfo) != EN_OK) {
632	                    return EN_ERROR;
633	                }
634	                break;
635	            default:
636	                return EN_ERROR;
637	        }
638	    }
639	
640	    return MsnConfigCmdCheck(argInfo);
641	}
