660	        "    --print              Set the output location of msnpureport logs, "
661	            "option: 0(syslog, default is 0), 1(stdout)\n"
662	        "    --log_level          Set log level of msnpureport, option: debug, info(default is info), warning, error\n"
663	        "    -h, --help           Help information\n"
664	    );
665	    printf(
666	        "\nExport device logs and files at a time:\n"
667	        "    -a, --all            Export all log and file, device event information in the bbox\n"
668	        "    -f, --force          Export all log and file, device event information in the bbox, "
669	            "historical maintenance and measurement information in the bbox\n"
670	        "    -t, --type           Export type: 0(all log and file, default is 0), 1(slog, message and system_info), "
671	    #ifdef UB_SUPPORT
672	            "2(bbox, current register), 3(stackcore), 4(vmcore), 5(module log), 6(ub)\n"
673	    #else
674	            "2(bbox, current register), 3(stackcore), 4(vmcore), 5(module log)\n"
675	    #endif
676	    );
677	    if (!MsnIsPoolEnv()) {
678	        printf(
679	            "\nContinuously exporting device logs:\n"
680	            "    --permanent          Continuously Exporting Device log flag, "
681	            "the following options must be entered after this flag\n"
682	            "    -o, --output         Set output path, must be relative path\n"
683	        );
684	        for (int32_t i = (int32_t)REPORT_ARGS_SYS_LOG_NUM; i <= (int32_t)REPORT_ARGS_DEVICE_APP_DIR_NUM; i++) {
685	            printf("%s, range [%d-%d], default %d\n", g_permanentHelpMsg[i], PERMANENT_ARGS_RANGE[i][MIN_INDEX],
686	                PERMANENT_ARGS_RANGE[i][MAX_INDEX], PERMANENT_ARGS_RANGE[i][DEFAULT_INDEX]);
687	        }
688	    }
689	}
690	
691	STATIC int32_t MsnSetReportType(ArgInfo *argInfo, const char *arg)
692	{
693	    int64_t num = -1;
694	    if (MsnOptionGetValueInRange(arg, "type|-t", &num, ALL_LOG, MAX_TYPE_NUM - 1) != EN_OK) {
695	        return EN_ERROR;
696	    }
697	
698	    argInfo->reportType = (int32_t)num;
699	    argInfo->subCmd = (uint32_t)REPORT_TYPE;
700	    return EN_OK;
701	}
702	
703	STATIC int32_t MsnReportParamCmd(int32_t opt, ArgInfo *argInfo, int32_t optionIndex)
704	{
705	
706	    FileAgeingParam *param = (FileAgeingParam *)argInfo->value;
707	    uint32_t *paramValue[REPORT_ARGS_OUTPUT + 1] = {
708	        [REPORT_ARGS_SYS_LOG_NUM] = &param->sysLogFileNum,
709	        [REPORT_ARGS_SYS_LOG_SIZE] = &param->sysLogFileSize,
710	        [REPORT_ARGS_FW_LOG_NUM] = &param->firmwareLogFileNum,
711	        [REPORT_ARGS_FW_LOG_SIZE] = &param->firmwareLogFileSize,
712	        [REPORT_ARGS_EVENT_LOG_NUM] = &param->eventLogFileNum,
713	        [REPORT_ARGS_EVENT_LOG_SIZE] = &param->eventLogFileSize,
714	        [REPORT_ARGS_SEC_LOG_NUM] = &param->securityLogFileNum,
715	        [REPORT_ARGS_SEC_LOG_SIZE] = &param->securityLogFileSize,
716	        [REPORT_ARGS_STACKCORE_NUM] = &param->stackcoreFileNum,
717	        [REPORT_ARGS_FAULT_EVENT_NUM] = &param->faultEventDirNum,
718	        [REPORT_ARGS_BBOX_NUM] = &param->bboxDirNum,
719	        [REPORT_ARGS_SLOGD_LOG_NUM] = &param->slogdLogFileNum,
720	        [REPORT_ARGS_DEVICE_APP_DIR_NUM] = &param->deviceAppDirNum,
721	    };
722	
723	    if (argInfo->cmdType != REPORT_PERMANENT) {
724	        if (opt == REPORT_ARGS_OUTPUT && optionIndex == 0) {
725	            MSNPU_PRINT_ERROR("Must input --permanent before input -o.");
726	        } else {
727	        MSNPU_PRINT_ERROR("Must input --permanent before input --%s.", g_reportOptions[optionIndex].name);
728	        }
729	        return EN_ERROR;
730	    }
731	    if (opt == REPORT_ARGS_OUTPUT) {
732	        if (param->outputFileName[0] != '\0') {
733	            MSNPU_PRINT_ERROR("Repeatedly input --%s.", g_reportOptions[optionIndex].name);
734	            return EN_ERROR;
735	        }
736	        if (strlen(mmGetOptArg()) >= MMPA_MAX_PATH) {
737	            MSNPU_PRINT_ERROR("Output path too long.");
738	            return EN_ERROR;
739	        }
740	        errno_t err = strcpy_s(param->outputFileName, MAX_VALUE_STR_LEN, mmGetOptArg());
741	        ONE_ACT_ERR_LOG(err != EOK, return EN_ERROR, "strcpy_s failed for output path.");
742	        return EN_OK;
743	    }
744	    if (*paramValue[opt] != 0) {
745	        MSNPU_PRINT_ERROR("Repeatedly input --%s.", g_reportOptions[optionIndex].name);
746	        return EN_ERROR;
747	    }
748	
749	    int64_t value = 0;
750	    if (MsnOptionGetValueInRange(mmGetOptArg(), g_reportOptions[optionIndex].name, &value,
751	        PERMANENT_ARGS_RANGE[opt][0], PERMANENT_ARGS_RANGE[opt][1]) != EN_OK) {
752	        return EN_INVALID_PARAM;
753	    }
754	
755	    *paramValue[opt] = (uint32_t)value;
756	    return EN_OK;
757	}
758	STATIC int32_t MsnReportPermanentCmd(int32_t opt, ArgInfo *argInfo, int32_t optionIndex)
759	{
760	    if (opt == (int32_t)REPORT_ARGS_PERMANENT) {
761	        if (argInfo->subCmd != REPORT_DEFAULT) {
762	            MSNPU_PRINT_ERROR("-a,-f,-t cannot be used together with --permanent.");
763	            return EN_INVALID_PARAM;
764	        }
765	        if (argInfo->cmdType == REPORT_PERMANENT) {
766	            MSNPU_PRINT_ERROR("Input --permanent repeatedly.");
767	            return EN_ERROR;
768	        }
769	        argInfo->cmdType = REPORT_PERMANENT;
770	        return EN_OK;
771	    }
772	    return MsnReportParamCmd(opt, argInfo, optionIndex);
773	}
774	
775	STATIC int32_t MsnReportLogCmd(int32_t opt, ArgInfo *argInfo)
776	{
777	    if (argInfo->cmdType != REPORT) {
778	        MSNPU_PRINT_ERROR("-a,-f,-t cannot be used together with --permanent.");
779	        return EN_INVALID_PARAM;
780	    }
781	    if (argInfo->subCmd != REPORT_DEFAULT) {
782	        MSNPU_PRINT_ERROR("-a,-f,-t only support one option at a time.");
783	        return EN_INVALID_PARAM;
784	    }
785	    switch (opt) {
786	        case REPORT_ARGS_REPORT_ALL:
787	            argInfo->subCmd = (uint32_t)REPORT_ALL;
788	            argInfo->reportType = (int32_t)ALL_LOG;
789	            break;
790	        case REPORT_ARGS_REPORT_FORCE:
791	            argInfo->subCmd = (uint32_t)REPORT_FORCE;
792	            argInfo->reportType = (int32_t)ALL_LOG;
793	            break;
794	        case REPORT_ARGS_REPORT_TYPE:
795	            if (MsnSetReportType(argInfo, mmGetOptArg())) {
796	                return EN_INVALID_PARAM;
797	            }
798	            break;
799	        default:
800	            return EN_ERROR;
801	    }
802	    return EN_OK;
803	}
804	
805	static int32_t MsnSetLogPrint(ArgInfo *argInfo, const char *arg)
806	{
807	    if (argInfo->printMode != INVALID_PRINT_MODE) {
808	        MSNPU_PRINT_ERROR("Duplicate input --print.");
809	        return EN_ERROR;
810	    }
811	
812	    if (strcmp(arg, "0") == 0) {
813	        argInfo->printMode = PRINT_SYSLOG;
814	    } else if (strcmp(arg, "1") == 0) {
815	        argInfo->printMode = PRINT_STDOUT;
816	    } else {
817	        MSNPU_PRINT_ERROR("Input --print %s is invalid, please input 0 or 1.", arg);
818	        return EN_INVALID_PARAM;
819	    }
820	    return EN_OK;
821	}
822	
823	static int32_t MsnSetSelfLogLevel(ArgInfo *argInfo, const char *arg)
824	{
825	    if (argInfo->selfLogLevel != SYSLOG_MAX_LEVEL) {
826	        MSNPU_PRINT_ERROR("Duplicate input --log_level.");
827	        return EN_ERROR;
828	    }
829	
830	    const char *logLevelMap[SYSLOG_MAX_LEVEL] = {
831	        [LOG_ERR] = LOG_LEVEL_ERROR_STR,
832	        [LOG_WARNING] = LOG_LEVEL_WARNING_STR,
833	        [LOG_INFO] = LOG_LEVEL_INFO_STR,
834	        [LOG_DEBUG] = LOG_LEVEL_DEBUG_STR,
835	    };
836	
837	    for (int32_t i = 0; i < SYSLOG_MAX_LEVEL; i++) {
838	        if ((logLevelMap[i] != NULL) && (strcmp(arg, logLevelMap[i]) == 0)) {
839	            argInfo->selfLogLevel = i;
840	            return EN_OK;
841	        }
842	    }
843	    MSNPU_PRINT_ERROR("Input --log_level %s is invalid, please input %s, %s, %s or %s.", arg, LOG_LEVEL_ERROR_STR,
844	        LOG_LEVEL_WARNING_STR, LOG_LEVEL_INFO_STR, LOG_LEVEL_DEBUG_STR);
845	    return EN_INVALID_PARAM;
846	}
847	
848	STATIC int32_t MsnReportCommonCmd(int32_t opt, ArgInfo *argInfo)
849	{
850	    switch (opt) {
851	        case REPORT_ARGS_DOCKER:
852	            if (MsnIsDockerEnv()) {
853	                argInfo->dockerFlag = 1;
854	                break;
855	            } else {
856	                MSNPU_PRINT_ERROR("--docker only used in docker env.");
857	                return EN_ERROR;
858	            }
859	            break;
860	        case REPORT_ARGS_PRINT:
861	            if (MsnSetLogPrint(argInfo, mmGetOptArg()) != EN_OK) {
862	                return EN_ERROR;
863	            }
864	            break;
865	        case REPORT_ARGS_MSN_LOG_LEVEL:
866	            if (MsnSetSelfLogLevel(argInfo, mmGetOptArg()) != EN_OK) {
867	                return EN_ERROR;
868	            }
869	            break;
870	        case REPORT_ARGS_DEVICE:
871	            if (MsnSetDeviceId(argInfo, mmGetOptArg()) != EN_OK) {
872	                return EN_ERROR;
873	            }
874	            break;
875	        case REPORT_ARGS_REPORT_HELP:
876	            MsnPrintReportHelp();
877	            return EN_ERROR;
878	        default:
879	            return EN_ERROR;
880	    }
881	    return EN_OK;
882	}
883	
884	STATIC int32_t MsnReportCmdCheck(ArgInfo *argInfo)
885	{
886	    if (argInfo->cmdType == REPORT) {
887	        if (argInfo->reportType == MAX_TYPE_NUM) {
888	            argInfo->reportType = ALL_LOG;
889	        }
890	    }
891	
892	    if (argInfo->cmdType == REPORT_PERMANENT) {
893	        FileAgeingParam *param = (FileAgeingParam *)argInfo->value;
894	        uint32_t *paramValue[REPORT_ARGS_DEVICE_APP_DIR_NUM + 1] = {
895	            [REPORT_ARGS_SYS_LOG_NUM] = &param->sysLogFileNum,
896	            [REPORT_ARGS_SYS_LOG_SIZE] = &param->sysLogFileSize,
897	            [REPORT_ARGS_FW_LOG_NUM] = &param->firmwareLogFileNum,
898	            [REPORT_ARGS_FW_LOG_SIZE] = &param->firmwareLogFileSize,
899	            [REPORT_ARGS_EVENT_LOG_NUM] = &param->eventLogFileNum,
900	            [REPORT_ARGS_EVENT_LOG_SIZE] = &param->eventLogFileSize,
901	            [REPORT_ARGS_SEC_LOG_NUM] = &param->securityLogFileNum,
902	            [REPORT_ARGS_SEC_LOG_SIZE] = &param->securityLogFileSize,
903	            [REPORT_ARGS_STACKCORE_NUM] = &param->stackcoreFileNum,
904	            [REPORT_ARGS_FAULT_EVENT_NUM] = &param->faultEventDirNum,
905	            [REPORT_ARGS_BBOX_NUM] = &param->bboxDirNum,
906	            [REPORT_ARGS_SLOGD_LOG_NUM] = &param->slogdLogFileNum,
907	            [REPORT_ARGS_DEVICE_APP_DIR_NUM] = &param->deviceAppDirNum,
908	        };
909	        for (int32_t i = REPORT_ARGS_SYS_LOG_NUM; i <= REPORT_ARGS_DEVICE_APP_DIR_NUM; i++) {
910	            *paramValue[i] = *paramValue[i] == 0U ? (uint32_t)PERMANENT_ARGS_RANGE[i][DEFAULT_INDEX] : *paramValue[i];
911	        }
912	    }
913	    return EN_OK;
914	}
915	
916	static void MsnAdaptDavidPool(void)
917	{
918	    if (MsnIsPoolEnv()) {
919	        uint32_t num = sizeof(g_reportOptions) / sizeof(mmStructOption);
920	        for (uint32_t i = 0; i < num; i++) {
921	            if ((g_reportOptions[i].name != NULL) && (strcmp(g_reportOptions[i].name, "permanent") == 0)) {
922	                g_reportOptions[i] = (mmStructOption){NULL, 0, NULL, 0};
923	                break;
924	            }
925	        }
926	    }
927	}
928	
929	STATIC int32_t MsnGetReportOptions(int32_t argc, char **argv, ArgInfo *argInfo)
930	{
931	    MsnAdaptDavidPool();
932	    argInfo->cmdType = REPORT;
933	    argInfo->subCmd = REPORT_DEFAULT;
934	    argInfo->reportType = (int32_t)MAX_TYPE_NUM;;
935	    int32_t opt = 0;
936	    int32_t optionIndex = 0;
937	    while ((opt = mmGetOptLong(argc, argv, REPORT_OPT, g_reportOptions, &optionIndex)) != -1) {
938	        if (((opt >= REPORT_ARGS_PERMANENT) && (opt <= REPORT_ARGS_DEVICE_APP_DIR_NUM)) ||
939	            opt == REPORT_ARGS_OUTPUT) {
940	            if (MsnReportPermanentCmd(opt, argInfo, optionIndex) != EN_OK) {
941	                return EN_INVALID_PARAM;
942	            }
943	            continue;
944	        }
945	        switch (opt) {
946	            case REPORT_ARGS_DOCKER:
947	            case REPORT_ARGS_PRINT:
948	            case REPORT_ARGS_MSN_LOG_LEVEL:
949	            case REPORT_ARGS_DEVICE:
950	            case REPORT_ARGS_REPORT_HELP:
951	                if (MsnReportCommonCmd(opt, argInfo) != EN_OK) {
952	                    return EN_ERROR;
953	                }
954	                break;
955	            case REPORT_ARGS_REPORT_ALL:
956	            case REPORT_ARGS_REPORT_FORCE:
957	            case REPORT_ARGS_REPORT_TYPE:
958	                if (MsnReportLogCmd(opt, argInfo) !=EN_OK) {
959	                    return EN_INVALID_PARAM;
960	                }
961	                break;
962	            default:
963	                return EN_ERROR;
964	        }
965	    }
966	
967	    return MsnReportCmdCheck(argInfo);
968	}
969	
970	STATIC int32_t MsnOptionsHandle(int32_t argc, char **argv, ArgInfo *argInfo)
971	{
972	    ONE_ACT_ERR_LOG(argv == NULL, return EN_ERROR, "argv is NULL.");
973	    ONE_ACT_ERR_LOG(argv[0] == NULL, return EN_ERROR, "argv[0] is NULL.");
974	
975	    if (strcmp(argv[0], CONFIG_STR) == 0) {
976	        if (MsnGetConfigOptions(argc, argv, argInfo) != EN_OK) {
977	            return EN_ERROR;
978	        }
979	    } else if (strcmp(argv[0], REPORT_STR) == 0) {
980	        if (MsnGetReportOptions(argc, argv, argInfo) != EN_OK) {
981	            return EN_ERROR;
982	        }
983	    } else if (strcmp(argv[0], HELP_STR) == 0) {
984	        MsnPrintHelp();
985	        return EN_ERROR;
986	    } else if (strcmp(argv[0], VERSION_STR) == 0) {
987	        MSNPU_PRINT("msnpureport version: %s", MSNPUREPORT_VERSION);
988	        return EN_ERROR;
989	    } else {
990	        MSNPU_PRINT_ERROR("Invalid subcommand: %s.", argv[0]);
991	        MsnPrintHelp();
992	    }
993	
994	    if (MsnIsDockerEnv() && !(argInfo->dockerFlag != 0)) {
995	        MSNPU_PRINT_ERROR("msnpureport in docker should be used with --docker.");
996	        return EN_ERROR;
997	    }
998	
999	    return EN_OK;
1000	}
1001	
1002	STATIC int32_t MsnHandleArgInfo(ArgInfo *argInfo)
1003	{
1004	    int32_t ret = EN_OK;
1005	    switch (argInfo->cmdType) {
1006	        case CONFIG_GET:
1007	        case CONFIG_SET:
1008	            if (argInfo->deviceId == MAX_DEV_NUM) {
1009	                argInfo->deviceId = 0;
1010	            }
1011	            ret = MsnConfig(argInfo);
1012	            break;
1013	        case REPORT:
1014	        case REPORT_PERMANENT:
1015	            ret = MsnReport(argInfo);
1016	            break;
1017	        case INVALID_CMD:
1018	        default:
1019	            ret = EN_ERROR;
1020	            break;
1021	    }
1022	    if (ret != EN_OK) {
1023	        MSNPU_PRINT_ERROR("Process failed, check syslog for more information.");
1024	    }
1025	    return ret;
1026	}
1027	
1028	int32_t MsnOptions(int32_t argc, char **argv)
1029	{
1030	    ONE_ACT_ERR_LOG(argv == NULL, return EN_ERROR, "argv is NULL.");
1031	    ArgInfo argInfo = {
1032	        .cmdType = INVALID_CMD,
1033	        .subCmd = (uint32_t)INVALID_TYPE,
1034	        .deviceId = MAX_DEV_NUM,
1035	        .valueLen = 0,
1036	        .coreSwitch = -1,
1037	        .reportType = 0,
1038	        .dockerFlag = 0,
1039	        .printMode = INVALID_PRINT_MODE,
1040	        .selfLogLevel = SYSLOG_MAX_LEVEL,
1041	        .value = {0}
1042	    };
1043	
1044	    if ((argc < MIN_USER_ARG_LEN) || ((argv[1] != NULL) && (argv[1][0] == '-'))) {
1045	        // old command
1046	        bool flag = true;
1047	        if (MsnOptionsOld(argc, argv, &argInfo, &flag) != EN_OK) {
1048	            return EN_ERROR;
1049	        }
1050	        if (!flag) {
1051	            return EN_OK;
1052	        }
1053	    } else {
1054	        // new command
1055	        if (MsnOptionsHandle(argc - 1, &argv[1], &argInfo) != EN_OK) {
1056	            return EN_ERROR;
1057	        }
1058	        optind++;       // To adapt subcommand
1059	    }
1060	
1061	    if (optind < argc) {
1062	        printf ("ERROR: Invalid option: ");
1063	        while (optind < argc) {
1064	            printf ("%s ", argv[optind++]);
1065	        }
1066	        putchar ('\n');
1067	        return EN_ERROR;
1068	    }
1069	
1070	    if (argInfo.printMode == INVALID_PRINT_MODE) {
1071	        argInfo.printMode = PRINT_SYSLOG;
1072	    }
1073	    if (argInfo.selfLogLevel == SYSLOG_MAX_LEVEL) {
1074	        argInfo.selfLogLevel = LOG_INFO;
1075	    }
1076	
1077	    MsnSetLogPrintMode(argInfo.printMode);
1078	    MsnPrintSetLogLevel(argInfo.selfLogLevel);
1079	    return MsnHandleArgInfo(&argInfo);
1080	}

