186	#ifdef HDC_NEW_CHANNEL
187	        ret = AdxGetSpecifiedFile((uint16_t)(threadArgInfo->phyId), fullPath, logPath,
188	            (int32_t)HDC_SERVICE_TYPE_PROFILING, (int32_t)COMPONENT_SYS_GET);
189	#else
190	        ret = AdxGetSpecifiedFile((uint16_t)(threadArgInfo->phyId), fullPath, logPath,
191	            (int32_t)HDC_SERVICE_TYPE_LOG, (int32_t)COMPONENT_SYS_GET);
192	#endif
193	    } else {
194	        ret = AdxGetDeviceFileTimeout((uint16_t)(threadArgInfo->phyId), fullPath, logPath, timeout);
195	    }
196	    if (ret != 0) {
197	        if (ret == BLOCK_RETURN_CODE) {
198	            SELF_LOG_ERROR("export files failed, can not export files in docker.");
199	        } else {
200	            SELF_LOG_ERROR("get device files failed by adx, device os %ld.", threadArgInfo->devOsId);
201	        }
202	        return EN_ERROR;
203	    }
204	    SELF_LOG_INFO("Export logs to dir succeed: %s/dev-os-%ld", hostFilePath, threadArgInfo->devOsId);
205	    return EN_OK;
206	}
