208	static int32_t GetSystemInfoLogs(const ThreadArgInfo *threadArgInfo)
209	{
210	    size_t itemNum = sizeof(MSNPUREPORT_FILE_DUMP_INFO) / sizeof(MSNPUREPORT_FILE_DUMP_INFO[0]);
211	    uint32_t mask = 1U << threadArgInfo->logType;
212	    for (size_t i = 0; i < itemNum; ++i) {
213	        if ((MSNPUREPORT_FILE_DUMP_INFO[i].type & mask) == 0) {
214	            continue;
215	        }
216	        if (GetSpecificLogs(threadArgInfo, threadArgInfo->logType,
217	            MSNPUREPORT_FILE_DUMP_INFO[i].label, MSNPUREPORT_FILE_DUMP_INFO[i].timeout) != EN_OK) {
218	            return EN_ERROR;
219	        }
220	    }
221	    return EN_OK;
222	}
