224	STATIC void* SlogSyncThread(void *arg)
225	{
226	    ONE_ACT_ERR_LOG(arg == NULL, return NULL, "arg of SlogSyncThread is null.");
227	    ThreadArgInfo *threadArgInfo = (ThreadArgInfo *)arg;
228	    char threadName[TMP_STR_SIZE] = {0};
229	    int32_t ret = 0;
230	    ret = sprintf_s(threadName, TMP_STR_SIZE, "MsnLogRecv%ld", threadArgInfo->devOsId);
231	    ONE_ACT_ERR_LOG(ret == -1, return NULL, "Call sprintf_s failed for thread name %ld.", threadArgInfo->devOsId);
232	    ret = ToolSetThreadName(threadName);
233	    NO_ACT_WARN_LOG(ret != SYS_OK, "can not set thread name %s.", threadName);
234	
235	    bool successFlag = true;
236	    if (!MsnIsPoolEnv()) {
237	        // create slog path and receive slog files
238	        if (GetSpecificLogs(threadArgInfo, (int32_t)SLOG_LOG, SLOG_PATH, DEFAULT_TIMEOUT) != EN_OK) {
239	            SELF_LOG_ERROR("export device app failed, device os %ld", threadArgInfo->devOsId);
240	            successFlag = false;
241	        }
242	        if (GetSpecificLogs(threadArgInfo, (int32_t)SLOG_LOG, SINGLE_EXPORT_LOG, DEFAULT_TIMEOUT) != EN_OK) {
243	            SELF_LOG_ERROR("export slog failed, device os %ld", threadArgInfo->devOsId);
244	            successFlag = false;
245	        }
246	    }
247	
248	    // create stackcore path and receive stackcore files
249	    if (GetSpecificLogs(threadArgInfo, (int32_t)STACKCORE_LOG, STACKCORE_PATH, DEFAULT_TIMEOUT) != EN_OK) {
250	        SELF_LOG_ERROR("export stackcore failed, device os %ld", threadArgInfo->devOsId);
251	        successFlag = false;
252	    }
253	    // create message path and receive message files
254	    if (GetSpecificLogs(threadArgInfo, (int32_t)SLOG_LOG, MESSAGE_PATH, DEFAULT_TIMEOUT) != EN_OK) {
255	        SELF_LOG_ERROR("export message failed, device os %ld", threadArgInfo->devOsId);
256	        successFlag = false;
257	    }
258	    // create system_info path and receive system_info files
259	    if (GetSystemInfoLogs(threadArgInfo) != EN_OK) {
260	        SELF_LOG_ERROR("export system_info failed, device os %ld", threadArgInfo->devOsId);
261	        successFlag = false;
262	    }
263	    // create event_sched path and receive event_sched files
264	    if (GetSpecificLogs(threadArgInfo, (int32_t)SLOG_LOG, EVENT_PATH, DEFAULT_TIMEOUT) != EN_OK) {
265	        SELF_LOG_ERROR("export event_sched failed, device os %ld", threadArgInfo->devOsId);
266	        successFlag = false;
267	    }
268	
269	    if (!successFlag) {
270	        MSNPU_FPRINTF("ERROR: export device os %ld files failed, check syslog for more information.\n",
271	            threadArgInfo->devOsId);
272	    }
273	    return NULL;
274	}
