276	static int32_t MsnReportCreateThreadForAllDevice(ThreadInfo *threadInfo, uint32_t threadNum, bool isUseMasterId)
277	{
278	    (void)threadNum;
279	    mmThreadAttr threadAttr = DEFAULT_JOINABLE_THREAD_ATTR;
280	
281	    bool devFlag[MAX_DEV_NUM] = { false };
282	    int64_t devOsId = 0;
283	    uint32_t i;
284	    for (i = 0; i < g_msnDeviceInfo.devNum; i++) {
285	        uint32_t logicId = g_msnDeviceInfo.devIds[i];
286	        if (isUseMasterId) {
287	            if (g_msnDeviceInfo.masterIds[logicId] == INVALID_MASTER_ID) {
288	                continue;
289	            }
290	            devOsId = g_msnDeviceInfo.masterIds[logicId];
291	        } else {
292	            if (logicId >= threadNum) {
293	                continue;
294	            }
295	            devOsId = (int64_t)logicId;
296	        }
297	        if (devFlag[devOsId] == true) {
298	            continue;
299	        }
300	        int32_t ret = mmCreateTaskWithThreadAttr(&threadInfo[logicId].tid, &threadInfo[logicId].block, &threadAttr);
301	        if (ret != EN_OK) {
302	            SELF_LOG_ERROR("create task(SlogSyncThread) failed, dev_id=%u, strerr=%s.",
303	                           g_msnDeviceInfo.devIds[i], strerror(mmGetErrorCode()));
304	            continue;
305	        }
306	        devFlag[devOsId] = true;
307	    }
308	    // all threads failed to be created, return ERROR
309	    for (i = 0; i < MAX_DEV_NUM; i++) {
310	        if (devFlag[i]) {
311	            return EN_OK;
312	        }
313	    }
314	    SELF_LOG_ERROR("All device thread create failed");
315	    return EN_ERROR;
316	}
