321	    for (uint32_t i = 0; i < g_msnDeviceInfo.devNum; i++) {
322	        if ((g_msnDeviceInfo.masterIds[g_msnDeviceInfo.devIds[i]] == masterId) && (idNum < size)) {
323	            logicIds[idNum] = g_msnDeviceInfo.devIds[i];
324	            idNum++;
325	        }
326	    }
327	    return idNum;
328	}
