379	 * @brief SlogStartSyncFile: start thread to sync device log files
380	 * @param [in]logType: log type
381	 * @return EN_OK/EN_ERROR
382	 */
383	static int SlogStartSyncFile(uint32_t logicId, int32_t logType)
384	{
385	    if (MsnReportInitDevInfo(logicId) != EN_OK) {
386	        return EN_ERROR;
387	    }
388	    errno_t err = memset_s(g_slogdThread, MAX_DEV_NUM * sizeof(ThreadInfo), 0, MAX_DEV_NUM * sizeof(ThreadInfo));
389	    if (err != EOK) {
390	        SELF_LOG_ERROR("Memset for g_slogdThread failed, ret:%d", err);
391	        return EN_ERROR;
392	    }
393	    MsnSetThreadInfo(g_slogdThread, g_threadArgInfo, SlogSyncThread, logType);
394	    if (logicId == MAX_DEV_NUM) {
395	        return MsnReportCreateThreadForAllDevice(g_slogdThread, MAX_DEV_NUM, true);
396	    } else {
397	        return MsnReportCreateThreadSingleOs(logicId, g_slogdThread, true);
398	    }
399	}
