401	static void MsnJoinThreads(ThreadInfo *threadInfo, uint32_t threadNum)
402	{
403	    int32_t ret = 0;
404	    for (uint32_t i = 0; i < threadNum; i++) {
405	        if (threadInfo[i].tid == 0) {
406	            continue;
407	        }
408	        ret = mmJoinTask(&threadInfo[i].tid);
409	        if (ret != EN_OK) {
410	            SELF_LOG_ERROR("pthread join failed, dev_id=%u, strerr=%s.", i, strerror(mmGetErrorCode()));
411	        }
412	        threadInfo[i].tid = 0;
413	    }
414	}
