446	/**
447	 * @brief BboxStartSyncFile: start to sync bbox files
448	 * @param [in]opt: bbox dump opt
449	 * @return EN_OK/EN_ERROR
450	 */
451	static int BboxStartSyncFile(uint32_t logicId, const struct BboxDumpOpt *opt, int32_t logType)
452	{
453	    if (logType == (int32_t)HISILOGS_LOG) {
454	        ExportDeviceRegister(logicId);
455	    }
456	    int32_t ret = 0;
457	    if (logicId == MAX_DEV_NUM) {
458	        ret = BboxStartDump(INVALID_DEV_ID, g_logPath, (int32_t)strlen(g_logPath), opt);
459	        ONE_ACT_ERR_LOG(ret != 0, return EN_ERROR, "start bbox dump failed.");
460	        // wait bbox sync thread stop
461	        BboxStopDump();
462	    } else {
463	        uint32_t logicIds[MAX_DEV_NUM] = { 0 };
464	        uint32_t logicNum = MsnGetAllLogicIdByMatserId(g_msnDeviceInfo.masterId, logicIds, MAX_DEV_NUM);
465	        for (uint32_t i = 0; i < logicNum; i++) {
466	            // the bbox interface does not support multiple device concurrency
467	            ret = BboxStartDump((int32_t)logicIds[i], g_logPath, (int32_t)strlen(g_logPath), opt);
468	            ONE_ACT_ERR_LOG(ret != BBOX_SUCCESS, return EN_ERROR, "Start bbox dump failed.");
469	            BboxStopDump();
470	        }
471	    }
472	    return EN_OK;
473	}
