477	    char *fullPath = (char *)calloc(1, MMPA_MAX_PATH + 1);
478	    ONE_ACT_ERR_LOG(fullPath == NULL, return, "calloc failed for host drv, strerr=%s.", strerror(mmGetErrorCode()));
