566	STATIC int32_t getDrvUBInfo(uint32_t devId, uint32_t ubDataType, void* buffer, uint32_t *bufferSizePtr) {
567	    (void)memset_s(buffer, MAX_UB_INFO_SIZE, 0, MAX_UB_INFO_SIZE);
568	    *bufferSizePtr = MAX_UB_INFO_SIZE;
569	    struct DsmiUbDfxInput* ubDfxInput = (struct DsmiUbDfxInput*)buffer;
570	    struct UbMamiStatsKey* UbMamiStatsKeyBufPtr = NULL;
571	    struct UbMamiTplAclQry* UbMamiTplAclQryBufPtr = NULL;
572	    struct UbQosSl2VlCmd* UbQosSl2VlCmdBufPtr = NULL;
573	    switch (ubDataType) {
574	        case UB_INFO_UBNL_DFX_STATISTIC:
575	            ubDfxInput->major = UB_MAMI_CMD_UBNL;
576	            ubDfxInput->minor = UB_INFO_UBNL_DFX_STATISTIC_PARAM_MINOR;
577	            ubDfxInput->buf_size = sizeof(struct UbMamiStatsKey);
578	            UbMamiStatsKeyBufPtr = (struct UbMamiStatsKey*)(ubDfxInput->buf);
579	            UbMamiStatsKeyBufPtr->idType = UB_INFO_UBNL_DFX_PARAM_ID_TYPE;
580	            UbMamiStatsKeyBufPtr->planeId = UB_INFO_UBNL_DFX_PARAM_PLANE_ID;
581	            break;
582	        case UB_INFO_UBNL_DFX_SSU_SCHEDULE:
583	            ubDfxInput->major = UB_MAMI_CMD_UBNL;
584	            ubDfxInput->minor = UB_INFO_UBNL_DFX_SSU_SCHEDULE_PARAM_MINOR;
585	            ubDfxInput->buf_size = sizeof(struct UbMamiStatsKey);
586	            UbMamiStatsKeyBufPtr = (struct UbMamiStatsKey*)(ubDfxInput->buf);
587	            UbMamiStatsKeyBufPtr->idType = UB_INFO_UBNL_DFX_PARAM_ID_TYPE;
588	            UbMamiStatsKeyBufPtr->planeId = UB_INFO_UBNL_DFX_PARAM_PLANE_ID;
589	            break;
590	        case UB_INFO_UBNL_DFX_CONFIG_ITEM:
591	            ubDfxInput->major = UB_MAMI_CMD_UBNL;
592	            ubDfxInput->minor = UB_INFO_UBNL_DFX_CONFIG_ITEM_PARAM_MINOR;
593	            ubDfxInput->buf_size = sizeof(struct UbMamiStatsKey);
594	            UbMamiStatsKeyBufPtr = (struct UbMamiStatsKey*)(ubDfxInput->buf);
595	            UbMamiStatsKeyBufPtr->idType = UB_INFO_UBNL_DFX_PARAM_ID_TYPE;
596	            UbMamiStatsKeyBufPtr->planeId = UB_INFO_UBNL_DFX_PARAM_PLANE_ID;
597	            break;
598	        case UB_INFO_UBMEM_DAW:
599	            ubDfxInput->major = UB_MAMI_CMD_UBMEM;
600	            ubDfxInput->minor = UB_INFO_UBMEM_DAW_PARAM_MINOR;
601	            ubDfxInput->buf_size = 0;
602	            break;
603	        case UB_INFO_UBTPL_ACL:
604	            ubDfxInput->major = UB_MAMI_CMD_UBTPL;
605	            ubDfxInput->minor = UB_INFO_UBTPL_ACL_PARAM_MINOR;
606	            ubDfxInput->buf_size = sizeof(struct UbMamiTplAclQry);
607	            UbMamiTplAclQryBufPtr = (struct UbMamiTplAclQry*)(ubDfxInput->buf);
608	            UbMamiTplAclQryBufPtr->fieldMask = UB_INFO_UBTPL_ACL_PARMA_MASK;
609	            UbMamiTplAclQryBufPtr->planeId = 0;
610	            break;
611	        case UB_INFO_SL_TO_VL:
612	            ubDfxInput->major = UB_MAMI_CMD_UBQOS;
613	            ubDfxInput->minor = UB_INFO_SL_TO_VL_PARAM_MINOR;
614	            ubDfxInput->buf_size = sizeof(struct UbQosSl2VlCmd);
615	            UbQosSl2VlCmdBufPtr = (struct UbQosSl2VlCmd*)(ubDfxInput->buf);
616	            UbQosSl2VlCmdBufPtr->plane_id = 0;
617	            UbQosSl2VlCmdBufPtr->num = UB_INFO_UBQOS_MAX_SL_NUM;
618	            *bufferSizePtr = sizeof(struct UbQosSl2VlCmd);
619	            break;
620	        default:
621	            SELF_LOG_WARN("UNSUPPORTED UB INFO TYPE:%u", ubDataType);
622	            break;
623	    }
624	    drvError_t err = dsmi_get_device_info(devId, DSMI_MAIN_CMD_UB, UB_SUB_CMD_UB_DFX_INFO, buffer, bufferSizePtr);
625	    return err;
626	}
