689	            SELF_LOG_ERROR("export files failed, please check error message.");
690	        }
691	    }
692	    int32_t err = 0;
693	    if ((logType == (int32_t)ALL_LOG) || (logType == (int32_t)HISILOGS_LOG) || (logType == (int32_t)VMCORE_FILE)) {
694	        mmDiskSize diskSize;
695	        (void)memset_s(&diskSize, sizeof(diskSize), 0, sizeof(diskSize));
696	        err =  mmGetDiskFreeSpace(g_logPath, &diskSize);
697	        if (err == EN_OK && diskSize.freeSize >= DEFAULT_BBOX_SIZE) {
698	        err = BboxStartSyncFile(logicId, opt, logType);
699	            ONE_ACT_ERR_LOG(err != EN_OK, return EN_ERROR, "start to sync bbox dump failed.");
700	        } else {
701	            ULONGLONG freeSize = diskSize.freeSize / 1024 / 1024;
702	            SELF_LOG_ERROR("No space left on device.");
703	            SELF_LOG_ERROR("Available space (%lluM) less than 10M. Bbox data will not be collected.", freeSize);
704	        }
705	    }
706	    #ifdef UB_SUPPORT
707	    if (logType == (int32_t)UB_LOG) {
