866	static int32_t MsnReportCreateLongLink(uint32_t devId, uint32_t timeout, void **handle, int32_t serverType,
867	    ComponentType compType)
868	{
869	    AdxCommHandle adxHandle = AdxCreateCommHandle(serverType, (int32_t)devId, compType);
870	    int32_t ret = AdxIsCommHandleValid(adxHandle);
871	    if (ret != IDE_DAEMON_OK) {
872	        SELF_LOG_ERROR("Adx create handle is invalid, devId=%u, ret=%d.", devId, ret);
873	        return EN_ERROR;
874	    }
875	
876	    // receive ack
877	    char *buffer = (char *)MsnMalloc(ACK_LEN);
878	    ONE_ACT_ERR_LOG(buffer == NULL, return EN_ERROR, "Malloc for ack buffer failed, devId=%u, strerr=%s.", devId,
879	                    strerror(ToolGetErrorCode()));
880	    uint32_t bufLen = ACK_LEN;
881	    do {
882	        ret = AdxRecvMsg(adxHandle, &buffer, &bufLen, timeout);
883	        if ((ret != IDE_DAEMON_OK) || (bufLen == 0U)) {
884	            SELF_LOG_ERROR("AdxRecvMsg failed, ret=%d, bufLen=%u bytes.", ret, bufLen);
885	            ret = EN_ERROR;
886	            break;
887	        }
888	        if (strcmp(buffer, HDC_END_MSG) == 0) {
889	            ret = EN_OK;
890	            break;
891	        }
892	        ret = EN_ERROR;
893	        if (strcmp(buffer, CONNECT_OCCUPIED_MESSAGE) == 0) {
894	            MSNPU_FPRINTF("Another msnpureport process is exporting logs of device os %u.\n", devId);
895	        } else if (strcmp(buffer, CONTAINER_NO_SUPPORT_MESSAGE) == 0) {
896	            MSNPU_FPRINTF("Not support export device log in container environment.\n");
897	        } else {
898	            SELF_LOG_ERROR("Get start messages failed, devId=%u, serverType=%d.", devId, serverType);
899	        }
900	    } while (0);
901	
902	    XFREE(buffer);
903	    if (ret != EN_OK) {
904	        AdxDestroyCommHandle(adxHandle);
905	        return EN_ERROR;
906	    }
907	
908	    *handle = (void *)adxHandle;
909	    return EN_OK;
910	}
