931	            ret = EN_ERROR;
932	            break;
933	        }
934	        if (buffer->retCode != 0) {
935	            SELF_LOG_ERROR("Get error message, devId=%u, ret=%d, errmsg=%s.", devId, buffer->retCode, buffer->retMsg);
936	            ret = EN_ERROR;
