942	    XFREE(buffer);
943	    if (ret != EN_OK) {
944	        AdxDestroyCommHandle(adxHandle);
945	        return EN_ERROR;
946	    }
947	
948	    *handle = (void *)adxHandle;
949	    return EN_OK;
