958	static void MsnReportSaveSlog(uint32_t devId, uint32_t timeout, void **handle, ThreadArgInfo *threadArgInfo)
959	{
960	    void *buffer = MsnMalloc(RECV_BUFF_SIZE);
961	    ONE_ACT_ERR_LOG(buffer == NULL, return, "Malloc slog receive buffer failed, devId=%u, strerr=%s", devId,
962	                    strerror(ToolGetErrorCode()));
963	
964	    uint32_t bufLen = 0;
965	    int32_t retryTime = 0;
966	    int32_t ret = 0;
967	    while ((retryTime < MAX_RETRY_TIME) && !threadArgInfo->isThreadExit) {
968	        if (AdxIsCommHandleValid(*handle) != IDE_DAEMON_OK) {
969	            retryTime++;
970	#ifdef HDC_NEW_CHANNEL
971	            ret = MsnReportCreateLongLink(devId, timeout, handle, HDC_SERVICE_TYPE_PROFILING, COMPONENT_SYS_REPORT);
972	#else
973	            ret = MsnReportCreateLongLink(devId, timeout, handle, HDC_SERVICE_TYPE_LOG, COMPONENT_SYS_REPORT);
974	#endif
975	            if (ret == EN_OK) {
976	                retryTime = 0;
977	                continue;
978	            }
979	            sleep(SLOGD_WAIT_TIME);
980	            continue;
981	        }
982	        bufLen = RECV_BUFF_SIZE;
983	        ret = AdxRecvMsg((AdxCommHandle)(*handle), (char **)&buffer, &bufLen, timeout);
984	        if ((ret != IDE_DAEMON_OK) || (bufLen == 0U)) {
985	            if (ret == IDE_DAEMON_SOCK_CLOSE) {        // 对端不存在, slogd 进程退出, 等待9s slogd重新被拉起
986	                SELF_LOG_WARN("Can not receive data, slogd process exit, try to connect again.");
987	                MsnReportReleaseHandle(handle);
988	                sleep(SLOGD_WAIT_TIME);
989	                continue;
990	            }
991	            usleep(RETRY_WAIT_TIME);
992	            continue;
993	        }
994	
995	        if (AdxSendMsg((AdxCommHandle)(*handle), HDC_END_MSG, strlen(HDC_END_MSG)) != EN_OK) {
996	            SELF_LOG_WARN("Can not send response message.");
997	        }
998	        (void)MsnFileMgrWriteDeviceSlog(buffer, bufLen, (uint32_t)threadArgInfo->devOsId);
999	        (void)memset_s(buffer, bufLen, 0, bufLen);
1000	    }
1001	    XFREE(buffer);
1002	}
