1131	        }
1132	        (void)memset_s(filename, MMPA_MAX_PATH, 0, MMPA_MAX_PATH);
1133	        ret = AdxRecvDevFileTimeout(handle, g_logPath, PERMANENT_TIMEOUT, filename, MMPA_MAX_PATH);
1134	        if (ret == IDE_DAEMON_OK) {
1135	            timeoutCount = 0;
1136	            (void)MsnFileMgrSaveFile(filename, MMPA_MAX_PATH, logicId);
1137	        } else if (ret == IDE_DAEMON_SOCK_CLOSE) {        // 对端不存在, log daemon 进程退出, 等待9s log daemon重新被拉起
1138	            SELF_LOG_WARN("Can not receive data, log daemon process exit, try to connect again.");
1139	            MsnReportReleaseHandle(&handle);
1140	            sleep(SLOGD_WAIT_TIME);
1141	        } else if (ret == (int32_t)IDE_DAEMON_HDC_TIMEOUT) {
1142	            usleep(RETRY_WAIT_TIME);
1143	            if ((timeoutCount == MAX_RECV_TIMEOUT_COUNT - 1) && (!MsnReportCheckDeviceAlive(logicId))) {
1144	                threadArgs->isThreadExit = true;
1145	            }
1146	            timeoutCount = (timeoutCount + 1) % MAX_RECV_TIMEOUT_COUNT;
1147	        } else {
1148	            usleep(RETRY_WAIT_TIME);
1149	        }
1150	    }
1151	    MsnReportBboxHBL(logicId, threadArgs);
1152	    threadArgs->isThreadExit = true;
1153	    MsnReportReleaseHandle(&handle);
1154	    SELF_LOG_WARN("Receive log daemon thread exited, device os %ld", threadArgs->devOsId);
1155	    return NULL;
1156	}
1157	
1158	STATIC void MsnReportFaultEventHandle(struct dsmi_event *event)
1159	{
1160	    uint32_t devId = event->event_t.dms_event.deviceid;
1161	    SELF_LOG_INFO("Receive fault event, event_id:0x%X, device id:%u, assertion:%u", event->event_t.dms_event.event_id, 
1162	                  devId, (uint8_t)event->event_t.dms_event.assertion);
1163	    if (event->event_t.dms_event.assertion == 0) {  // 故障恢复
1164	        return;
1165	    }
1166	
1167	    // 筛选出要监控的 device
1168	    if ((g_msnDeviceInfo.devId != MAX_DEV_NUM) && (g_msnDeviceInfo.masterIds[devId] != g_msnDeviceInfo.masterId)) {
1169	        return;
1170	    }
1171	
1172	    uint32_t phyId = 0;
1173	    drvError_t err = DRV_ERROR_NONE;
1174	    err = drvDeviceGetPhyIdByIndex(devId, &phyId);
1175	    ONE_ACT_ERR_LOG(err != DRV_ERROR_NONE, return, "Get physical id failed, logic id:%u", devId);
1176	
1177	    char relativePath[MMPA_MAX_PATH] = {0};
1178	    char absolutePath[MMPA_MAX_PATH] = {0};
1179	    int32_t ret = 0;
1180	    ret = sprintf_s(relativePath, MMPA_MAX_PATH, "%s/device-%u/fault_event_0x%X_", SYSTEM_INFO_PATH, phyId,
1181	        event->event_t.dms_event.event_id);
1182	    ONE_ACT_ERR_LOG(ret == -1, return, "Call sprintf_s failed.");
1183	    ret = MsnGetTimeStr(relativePath + (int32_t)strlen(relativePath), MMPA_MAX_PATH - (int32_t)strlen(relativePath));
1184	    ONE_ACT_ERR_LOG(ret == EN_ERROR, return, "Get time stamp failed.");
1185	    (void)MsnFileMgrSaveFile(relativePath, MMPA_MAX_PATH, phyId);
1186	
1187	    ret = sprintf_s(absolutePath, MMPA_MAX_PATH, "%s/%s", g_logPath, relativePath);
1188	    ONE_ACT_ERR_LOG(ret == -1, return, "Call sprintf_s failed.");
1189	    size_t itemNum = sizeof(MSNPUREPORT_FILE_DUMP_INFO) / sizeof(MsnpureportFileDumpTable);
1190	    for (uint32_t i = 0; i < (uint32_t)itemNum; i++) {
1191	        ret = AdxGetDeviceFileTimeout((uint16_t)phyId, absolutePath, MSNPUREPORT_FILE_DUMP_INFO[i].label,
1192	            MSNPUREPORT_FILE_DUMP_INFO[i].timeout);
1193	        NO_ACT_WARN_LOG(ret != IDE_DAEMON_OK, "Get %s failed.", MSNPUREPORT_FILE_DUMP_INFO[i].label);
1194	    }
1195	
1196	    (void)memset_s(absolutePath, MMPA_MAX_PATH, 0, MMPA_MAX_PATH);
1197	    ret = sprintf_s(absolutePath, MMPA_MAX_PATH, "%s/%s/%s", g_logPath, relativePath, MESSAGE_PATH);
1198	    ONE_ACT_ERR_LOG(ret == -1, return, "Call sprintf_s for message failed.");
1199	    ret = AdxGetDeviceFileTimeout((uint16_t)phyId, absolutePath, MESSAGE_PATH, DEFAULT_TIMEOUT);
1200	    NO_ACT_WARN_LOG(ret != IDE_DAEMON_OK, "Get message failed.");
1201	
1202	    (void)memset_s(absolutePath, MMPA_MAX_PATH, 0, MMPA_MAX_PATH);
1203	    ret = sprintf_s(absolutePath, MMPA_MAX_PATH, "%s/%s/%s", g_logPath, relativePath, EVENT_PATH);
1204	    ONE_ACT_ERR_LOG(ret == -1, return, "Call sprintf_s for event_sched failed.");
1205	    ret = AdxGetDeviceFileTimeout((uint16_t)phyId, absolutePath, EVENT_PATH, DEFAULT_TIMEOUT);
1206	    NO_ACT_WARN_LOG(ret != IDE_DAEMON_OK, "Get event_sched failed.");
1207	    SELF_LOG_INFO("Save file %s finish.", relativePath);
1208	}
1209	
1210	static int32_t MsnReportSubscribeFaultEvent(void)
1211	{
1212	    g_drvDsmiLibHandle = dlopen(DRV_DSMI_LIB, RTLD_NOW | RTLD_GLOBAL | RTLD_NODELETE);
1213	    ONE_ACT_ERR_LOG(g_drvDsmiLibHandle == NULL, return EN_ERROR, "Dlopen api from %s failed, dlopen error: %s",
1214	                    DRV_DSMI_LIB, dlerror())
1215	    DsmiSubscribeFaultEvent func = (DsmiSubscribeFaultEvent)dlsym(g_drvDsmiLibHandle, "dsmi_subscribe_fault_event");
1216	    ONE_ACT_ERR_LOG(func == NULL, return EN_ERROR, "Dlsym api dsmi_read_fault_event failed.");
1217	    struct dsmi_event_filter filter = { 0 };
1218	    int32_t ret = func(-1, filter, MsnReportFaultEventHandle);
1219	    ONE_ACT_ERR_LOG(ret != 0, return EN_ERROR, "Call dsmi_subscribe_fault_event failed, ret:%d", ret);
1220	
1221	    return EN_OK;
1222	}
1223	
1224	STATIC void MsnReportPermanentStop(void)
1225	{
1226	    int32_t ret = 0;
1227	    for (int32_t i = 0; i < MAX_DEV_NUM; i++) {
1228	        if (g_slogdThread[i].tid != 0) {
1229	            ret = mmJoinTask(&g_slogdThread[i].tid);
1230	            if (ret != EN_OK) {
1231	                SELF_LOG_ERROR("Join slogd thread failed, dev_id=%d, strerr=%s.", i, strerror(mmGetErrorCode()));
1232	            }
1233	            g_slogdThread[i].tid = 0;
1234	        }
1235	        if (g_logDaemonThread[i].tid != 0) {
1236	            ret = mmJoinTask(&g_logDaemonThread[i].tid);
1237	            if (ret != EN_OK) {
1238	                SELF_LOG_ERROR("Join log daemon thread failed, dev_id=%d, strerr=%s.", i, strerror(mmGetErrorCode()));
1239	            }
1240	            g_logDaemonThread[i].tid = 0;
1241	        }
1242	    }
1243	}
1244	
1245	STATIC int32_t MsnReportCreateThread(uint32_t devId)
1246	{
1247	    int32_t ret = 0;
1248	    MsnSetThreadInfo(g_slogdThread, g_threadArgInfo, MsnReportRecvSlogd, ALL_LOG);
1249	    MsnSetThreadInfo(g_logDaemonThread, g_threadArgInfo, MsnReportRecvLogDaemon, ALL_LOG);
1250	    if (devId != MAX_DEV_NUM) {
1251	        ret = MsnReportCreateThreadSingleOs(devId, g_slogdThread, true);
1252	        ONE_ACT_ERR_LOG(ret == EN_ERROR, return EN_ERROR, "Create slogd Thread failed.");
1253	        ret = MsnReportCreateThreadSingleOs(devId, g_logDaemonThread, true);
1254	        // if failed, return EN_OK to ensure the slogd thread can be joined
1255	        ONE_ACT_ERR_LOG(ret == EN_ERROR, return EN_OK, "Create log daemon Thread failed.");
1256	    } else {
1257	        ret = MsnReportCreateThreadForAllDevice(g_slogdThread, MAX_DEV_NUM, true);
1258	        ONE_ACT_ERR_LOG(ret == EN_ERROR, return EN_ERROR, "Create slogd Thread failed.");
1259	        ret = MsnReportCreateThreadForAllDevice(g_logDaemonThread, MAX_DEV_NUM, true);
1260	        ONE_ACT_ERR_LOG(ret == EN_ERROR, return EN_OK, "Create log daemon Thread failed.");
1261	    }
1262	
1263	    return EN_OK;
1264	}
1265	
1266	STATIC int32_t MsnReportPermanent(uint32_t devId, FileAgeingParam *param)
1267	{
1268	    // Verifying the root Permission
1269	    if (!IsHaveExecPermission()) {
1270	        SELF_LOG_ERROR("Not have permission to export files.");
1271	        return EN_ERROR;
1272	    }
1273	    bool setPathFlag = false;
1274	    // create directory
1275	    if (param->outputFileName[0] == '\0') {
1276	    if (CreateLogRootPath() != EN_OK) {
1277	        return EN_ERROR;
1278	    }
1279	    } else {
1280	        if (SetLogRootPath(param->outputFileName) != EN_OK) {
1281	            SELF_LOG_ERROR("SetLogRootPath failed");
1282	            return EN_ERROR;
1283	        }
1284	        setPathFlag = true;
1285	    }
1286	    if (MsnReportInitDevInfo(devId) != EN_OK) {
1287	        return EN_ERROR;
1288	    }
1289	
1290	    // init param
1291	    if (MsnFileMgrInit(param, g_logPath) != EN_OK) {
1292	        return EN_ERROR;
1293	    }
1294	    if (setPathFlag) {
1295	        SELF_LOG_INFO("Scanning and aging existing files in %s", g_logPath);
1296	        if (MsnFileMgrScanAndAge(g_logPath) != EN_OK) {
1297	            SELF_LOG_WARN("Scan and age existing files failed, continue anyway.");
1298	        }
1299	    }
1300	
1301	    // subscriber fault event
1302	    int32_t ret = MsnReportSubscribeFaultEvent();
1303	    if (ret == EN_OK) {
1304	        // create thread
1305	        ret = MsnReportCreateThread(devId);
1306	        if (ret == EN_OK) {
1307	            MsnReportPermanentStop();
1308	        }
1309	    }
1310	
1311	    if (g_drvDsmiLibHandle != NULL) {
1312	        dlclose(g_drvDsmiLibHandle);
1313	    }
1314	    MsnFileMgrExit();
1315	    MSNPU_FPRINTF("ERROR: Continuous export failed, check syslog for more information.\n");
1316	    return ret;
1317	}
1318	
1319	int32_t MsnReport(ArgInfo *argInfo)
1320	{
1321	    if (argInfo->cmdType == REPORT_PERMANENT) {
1322	        return MsnReportPermanent(argInfo->deviceId, (FileAgeingParam *)argInfo->value);
1323	    }
1324	
1325	    struct BboxDumpOpt bboxDumpOpt = { false, false, false, false, argInfo->printMode, argInfo->selfLogLevel };
1326	    if (argInfo->subCmd == REPORT_ALL) {
1327	        bboxDumpOpt.all = true;
1328	    } else if ((argInfo->subCmd == REPORT_FORCE) ||
1329	               ((argInfo->subCmd == REPORT_TYPE) && (argInfo->reportType == HISILOGS_LOG))) {
1330	        bboxDumpOpt.force = true;
1331	    } else if (argInfo->reportType == VMCORE_FILE) {
1332	        bboxDumpOpt.vmcore = true;
1333	    }
