#ifndef MSNPUREPORT_COMMON_H
#define MSNPUREPORT_COMMON_H

#include <stdint.h>
#include <stdbool.h>

#ifdef _LOG_UT_
#define STATIC
#define INLINE
#else
#define STATIC static
#define INLINE inline
#endif

enum CmdType {
    CONFIG_GET,
    CONFIG_SET,
    REPORT,
    REPORT_PERMANENT,
    INVALID_CMD
};

enum ConfigType {
    LOG_LEVEL = 0,
    ICACHE_RANGE,
    ACCELERATOR_RECOVER,
    AIC_SWITCH,
    AIV_SWITCH,
    SINGLE_COMMIT,
    INVALID_TYPE
};

enum ReportType {
    REPORT_DEFAULT = 0,
    REPORT_ALL,
    REPORT_FORCE,
    REPORT_TYPE,
};

#define MAX_VALUE_STR_LEN 4096
#define MIN_USER_ARG_LEN 2

typedef struct {
    enum CmdType cmdType;
    uint32_t subCmd;
    uint16_t deviceId;
    uint16_t valueLen;
    int32_t coreSwitch;
    int32_t reportType;
    int32_t dockerFlag;
    int32_t printMode;
    int32_t selfLogLevel;
    char value[MAX_VALUE_STR_LEN + 64];
} ArgInfo;

struct MsnReq {
    enum CmdType cmdType;
    uint32_t subCmd;
    uint32_t valueLen;
    char value[0];
};

struct ConfigInfo {
    uint32_t len;
    bool isError;
    char value[0];
};

typedef struct {
    uint32_t sysLogFileNum;
    uint32_t sysLogFileSize;
    uint32_t eventLogFileNum;
    uint32_t eventLogFileSize;
    uint32_t securityLogFileNum;
    uint32_t securityLogFileSize;
    uint32_t firmwareLogFileNum;
    uint32_t firmwareLogFileSize;
    uint32_t stackcoreFileNum;
    uint32_t slogdLogFileNum;
    uint32_t deviceAppDirNum;
    uint32_t faultEventDirNum;
    uint32_t bboxDirNum;
    char outputFileName[MAX_VALUE_STR_LEN];
} FileAgeingParam;

#define MAX_ICACHE_CHECK_RANGE (128U * 1024U)   // 128M
#define DISABLE_CORE 0
#define ENABLE_CORE 1
#define RESTORE_CORE 2

enum {
    CORE_ID0 = 0,
    CORE_ID1,
    CORE_ID2,
    CORE_ID3,
    CORE_ID_MAX
};

// define by TS
typedef struct {
    uint8_t coreSwitch;  // 0: disable 1:enable 2:restore
    uint8_t configNum;
    uint8_t coreId[CORE_ID_MAX];
    uint8_t resv[14];
} DfxCoreSetMask;
// define by TS
typedef struct {
    uint32_t value;  // 通用log dfx配置值
    uint8_t resv[16];
} DfxCommon;

#endif // MSNPUREPORT_COMMON_H

 *
 * adx 命令请求列表
 */
typedef enum cmd_class CmdClassT;

/**
 * @ingroup adx
 *
 * adx 数据交互格式
 */
struct tlv_req {
    enum cmd_class type; /**< 数据包命令类型 */
    int dev_id;          /**< 设备 ID */
    int len;             /**< 数据包数据长度 */
    char value[0];       /**< 数据包数据 */
};

/**
 * @ingroup adx
 *
 * adx 数据交互格式
 */
typedef struct tlv_req TlvReqT;
typedef TlvReqT* IdeTlvReq;
typedef const TlvReqT* IdeTlvConReq;
typedef IdeTlvReq* IdeTlvReqAddr;

#ifdef __cplusplus
}
#endif

